import { 
  TrendingUp, 
  TrendingDown, 
  CreditCard, 
  Users,
  Briefcase,
  ShieldCheck,
  AlertCircle
} from 'lucide-react'
import Link from 'next/link'
import { formatCurrency } from '@/lib/utils'
import { getDashboardStats, getRecentAuditLogs } from '@/lib/data'

export default async function DashboardPage() {
  // Use high-performance cached data
  const [statsData, auditLogs] = await Promise.all([
    getDashboardStats(),
    getRecentAuditLogs()
  ])

  const stats = [
    { name: 'Total Revenue', value: statsData.totalRevenue, icon: TrendingUp, color: 'text-emerald-600', bg: 'bg-emerald-50' },
    { name: 'Total Expenses', value: statsData.totalExpenses, icon: TrendingDown, color: 'text-rose-600', bg: 'bg-rose-50' },
    { name: 'Net Profit', value: statsData.netProfit, icon: CreditCard, color: 'text-slate-900', bg: 'bg-[#f7f7dc]' },
    { name: 'Order Book', value: statsData.orderBookValue, icon: Briefcase, color: 'text-indigo-600', bg: 'bg-indigo-50' },
    { name: 'Outstanding', value: statsData.outstanding, icon: Users, color: 'text-amber-600', bg: 'bg-amber-50' },
  ]

  return (
    <div className="space-y-10 animate-in fade-in duration-700">
      <div>
        <h2 className="text-3xl font-black tracking-tight text-slate-900 mb-2 uppercase">Financial Analytics</h2>
        <p className="text-slate-500 font-black uppercase tracking-[0.2em] text-[10px]">Real-time Performance Metrics • Internal Ledger</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-6">
        {stats.map((stat) => (
          <div key={stat.name} className="glass-card p-8 group hover:border-slate-900 transition-all duration-300">
            <div className="flex justify-between items-start mb-6">
              <div className={`p-4 rounded-2xl ${stat.bg} ${stat.color} border border-transparent group-hover:border-current transition-all`}>
                <stat.icon className="w-5 h-5" />
              </div>
            </div>
            <div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2">{stat.name}</p>
              <h3 className="text-3xl font-black text-slate-900 tracking-tight">{formatCurrency(stat.value)}</h3>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 glass-card p-8 bg-white">
          <div className="flex justify-between items-center mb-10">
            <h3 className="text-xl font-bold text-slate-900 uppercase tracking-tight">Revenue vs Expenses</h3>
            <div className="flex gap-6">
              <div className="flex items-center gap-2">
                <div className="w-2.5 h-2.5 rounded-full bg-slate-900" />
                <span className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Revenue</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-2.5 h-2.5 rounded-full bg-rose-500" />
                <span className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Expenses</span>
              </div>
            </div>
          </div>
          <div className="h-80 w-full rounded-2xl border border-slate-200 bg-slate-50/50 p-6">
            <div className="flex h-full flex-col justify-end gap-3">
              {statsData.totalRevenue === 0 && statsData.totalExpenses === 0 ? (
                <div className="flex h-full items-center justify-center text-slate-400 text-xs font-bold uppercase tracking-[0.2em]">
                  No revenue/expense activity yet this month
                </div>
              ) : (
                <>
                  <div className="text-[10px] font-black uppercase tracking-widest text-slate-500">This month</div>
                  <div className="space-y-4">
                    {[
                      { label: 'Revenue', value: statsData.totalRevenue, color: 'bg-slate-900' },
                      { label: 'Expenses', value: statsData.totalExpenses, color: 'bg-rose-500' },
                    ].map((row) => {
                      const max = Math.max(statsData.totalRevenue, statsData.totalExpenses, 1)
                      const pct = Math.max(0, Math.min(100, (row.value / max) * 100))
                      return (
                        <div key={row.label} className="space-y-2">
                          <div className="flex items-center justify-between text-[10px] font-black uppercase tracking-widest text-slate-600">
                            <span>{row.label}</span>
                            <span className="text-slate-900">{formatCurrency(row.value)}</span>
                          </div>
                          <div className="h-2 w-full rounded-full bg-white border border-slate-200 overflow-hidden">
                            <div className={`h-full ${row.color}`} style={{ width: `${pct}%` }} />
                          </div>
                        </div>
                      )
                    })}
                  </div>
                </>
              )}
            </div>
          </div>
        </div>

        <div className="glass-card p-8 bg-white relative overflow-hidden">
          <div className="absolute top-0 right-0 p-4 opacity-5">
            <ShieldCheck className="w-24 h-24 text-slate-900" />
          </div>
          <h3 className="text-xl font-bold text-slate-900 mb-8 uppercase tracking-tight relative z-10">Integrity Alerts</h3>
          <div className="space-y-6 relative z-10">
            {(auditLogs || []).length > 0 ? (
              auditLogs?.map((log) => (
                <Link
                  key={log.id}
                  href={`/audit?focus=${encodeURIComponent(String(log.id))}`}
                  className="flex items-center justify-between p-5 rounded-2xl bg-slate-50 border border-slate-100 hover:border-slate-900 transition-all group"
                >
                  <div>
                    <p className="text-[11px] font-black text-slate-900 uppercase tracking-wider">{log.action_type} • {log.record_type}</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">
                      {new Date(log.created_at).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}
                    </p>
                  </div>
                  <AlertCircle className="w-4 h-4 text-slate-300 group-hover:text-slate-900 transition-colors" />
                </Link>
              ))
            ) : (
              <div className="text-center py-10">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">No recent audit activity</p>
              </div>
            )}
            <Link
              href="/audit"
              className="w-full py-4 text-center text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 hover:text-slate-900 hover:bg-slate-50 rounded-2xl transition-all mt-4 border border-transparent hover:border-slate-200"
            >
              View Audit Ledger
            </Link>
          </div>
        </div>
      </div>
    </div>
  )
}
